styles.tutorial:
section[data-skill-hub] .content {
  min-height: calc(var(--vh, 1vh) * 100);
  position: relative;
  z-index: 20;
  background-color: var(--c-black);
  color: var(--c-white);
}
section[data-skill-hub] .footer {
  position: relative;
  background-color: #3687FF;
  color: var(--c-white);
}
section[data-skill-hub] .footer::after {
  content: '';
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--c-black);
  opacity: calc( 1 - var(--progress) );
  pointer-events: none;
}
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  align-items: start;
  column-gap: var(--g-gap);
}
section[data-skill-hub] .footer .-w {
  grid-template-rows: auto auto 1fr auto;
  min-height: calc(var(--vh, 1vh) * 100);
  transform: translate3d(0,calc( -50% + 50% * var(--progress) ),0);
}

section[data-skill-hub] .title {
  grid-column-start: 1;
  grid-column-end: 15;
  margin-top: var(--large);
}
@media (min-width: 1024px) {
  section[data-skill-hub] .title {
    grid-column-start: 4;
    grid-column-end: 12;
  }
}
section[data-skill-hub] .cta-title {
  grid-row: 2;
  grid-column-start: 1;
  grid-column-end: 8;
  margin-top: var(--h3);
  padding-right: var(--p);
}
@media (min-width: 1024px) {
  section[data-skill-hub] .cta-title {
    grid-column-start: 5;
    grid-column-end: 8;
  }
}
section[data-skill-hub] .cta-caption {
  grid-row: 2;
  grid-column-start: 8;
  grid-column-end: 15;
  margin-top: var(--h3);
  padding-top: 0.25em;
}
@media (min-width: 1024px) {
  section[data-skill-hub] .cta-caption {
    grid-column-start: 8;
    grid-column-end: 11;
  }
}
section[data-skill-hub] .button {
  grid-row: 3;
  grid-column-start: 8;
  grid-column-end: 10;
  justify-self: start;
  margin-top: var(--p);
  display: inline-block;
  padding: var(--mm) var(--p);
  background-color: #3687FF;
  border-radius: var(--g-gap);
}

section[data-skill-hub] span.logo {
  grid-column-start: 1;
  grid-column-end: 7;
  justify-self: start;
  margin-top: calc( var(--h0) + var(--h3) );
}
@media (min-width: 1024px) {
  section[data-skill-hub] span.logo {
    grid-column-start: 3;
    grid-column-end: 7;
  }
}
section[data-skill-hub] nav {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
section[data-skill-hub] nav.menu {
  grid-row: 2;
  grid-column-start: 1;
  grid-column-end: 8;
  margin-top: var(--h5);
}
@media (min-width: 1024px) {
  section[data-skill-hub] nav.menu {
    grid-row: 1;
    grid-column-start: 8;
    grid-column-end: 11;
    margin-top: calc( var(--h0) + var(--h3) );
  }
}
section[data-skill-hub] nav.help {
  grid-row: 2;
  grid-column-start: 8;
  grid-column-end: 15;
  margin-top: var(--h5);
}
@media (min-width: 1024px) {
  section[data-skill-hub] nav.help {
    grid-row: 1;
    grid-column-start: 11;
    grid-column-end: 15;
    margin-top: calc( var(--h0) + var(--h3) );
  }
}

section[data-skill-hub] nav.legal {
  grid-row: 3;
  grid-column-start: 1;
  grid-column-end: 8;
  margin-top: var(--h0);
}
@media (min-width: 1024px) {
  section[data-skill-hub] nav.legal {
    grid-row: 2;
    grid-column-start: 8;
    grid-column-end: 11;
  }
}
section[data-skill-hub] nav.socials {
  grid-row: 3;
  grid-column-start: 8;
  grid-column-end: 15;
  margin-top: var(--h0);
}
@media (min-width: 1024px) {
  section[data-skill-hub] nav.socials {
    grid-row: 2;
    grid-column-start: 11;
    grid-column-end: 15;
  }
}
section[data-skill-hub] .copy {
  grid-row: 5;
  grid-column-start: 1;
  grid-column-end: 8;
  justify-self: start;
  margin-top: var(--h0);
  margin-bottom: calc( var(--h0) * 2);
}
@media (min-width: 1024px) {
  section[data-skill-hub] .copy {
    grid-row: 4;
    grid-column-start: 3;
    grid-column-end: 11;
    margin-bottom: var(--h0);
  }
}
